export const BODY: string = "\n<p>صورة مائلة تُصلح في ثوانٍ عندما تعرف الخطوات: لا حاجة لتثبيت برنامج أو إنشاء حساب، وكل العمل يعمل في متصفحك.</p>\n<p>في هذا البرنامج التعليمي نمر بالعملية من الرفع إلى التنزيل: سنرى الدورانات السريعة 90 درجة والزوايا المخصصة للصور المائلة والقلبات الأفقية للصور الشخصية المعكوسة.</p>\n<p>في النهاية ستعرف كيف تصحح صورة واحدة ودفعة كاملة والأخطاء الشائعة التي تضيع الوقت. وأبقِ الملف الأصلي في متناول اليد حتى تراجع النتيجة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: ما تحتاجه</h2>\n<p>تحتاج ملف الصورة، محفوظًا على جهازك أو جاهزًا للصق من الحافظة: تقبل الأداة ملفات JPG وPNG وWebP وHEIC وGIF وBMP وSVG حتى 20 MB لكل ملف.</p>\n<p>اعمل من الملف الأصلي، لا من نسخة دُوّرت أو ضُغطت مسبقًا: كل حفظ إضافي يضيف قليلًا من الضرر إلى JPG، فأنظف نتيجة تأتي من أول تعديل. وقرر ما الخطأ قبل فتح الأداة: هل الصورة مائلة أم مقلوبة أم مائلة بضع درجات أم معكوسة؟ الجواب يخبرك إن كنت تدوّر أو تقلب أو تفعل الاثنين.</p>\n<p>افتح <a href=\"/ar/tadweer-wa-qalb-as-sura/\">أداة تدوير وقلب الصورة</a> في متصفحك. كل شيء يعمل محليًا، فصورتك لا تُرفع أبدًا إلى خادم.</p>\n<h2 id=\"step-by-step\">كيف تدوّر صورة في ست خطوات</h2>\n<p>العملية نفسها لصورة واحدة ولدفعة: أولًا يُرفع، ثم يُختار الحركة، وتُراجع المعاينة، ويُنزّل النتيجة.</p>\n<p>لإصلاح سريع، أزرار 90 درجة هي كل ما تحتاجه. ولأفق مائل، استخدم منزلق الزاوية المخصصة وراقب المعاينة وأنت تسحبه. وراجع الملف المنزّل قبل استخدامه: افتحه مرة وتأكد من أن الاتجاه صحيح وبعدها فقط أرفقه بنموذج أو انشره.</p>\n<ol>\n<li>ارفع صورتك بسحبها إلى منطقة الرفع أو اختيارها من جهازك أو لصقها بـCtrl+V.</li>\n<li>انقر تدوير 90° إلى اليسار أو تدوير 90° إلى اليمين أو 180° في دوران سريع وقلب لدوران قياسي.</li>\n<li>لصورة مائلة، اسحب منزلق زاوية التدوير إلى الدرجة الدقيقة التي تحتاجها ثم انقر تطبيق الزاوية.</li>\n<li>انقر قلب أفقي لعكس صورة شخصية معكوسة، أو قلب عمودي لقلب لقطة مقلوبة.</li>\n<li>انقر قارن على بطاقة الصورة لرؤية الاتجاه قبل وبعد، جنبًا إلى جنب.</li>\n<li>انقر تنزيل لملف واحد، أو تنزيل الكل (ZIP) عندما دوّرت دفعة كاملة.</li>\n</ol>\n<h2 id=\"choosing-the-right-angle\">كيف تختار الزاوية الصحيحة</h2>\n<p>صورة تُعرض مائلة تحتاج 90 درجة في اتجاه واحد: إذا تركتها المحاولة الأولى أسوأ، فالاتجاه الآخر هو الصحيح، فتراجع ودوّر إلى الجانب الآخر.</p>\n<p>صورة تُعرض مقلوبة تحتاج 180 درجة: لا شك هنا، لأن نصف دوران متساوٍ في أي اتجاه. وأفق مائل يحتاج زاوية مخصصة، غالبًا بين درجة وعشر درجات: الخطوات الصغيرة أفضل من الكبيرة، لأن العين تلاحظ حتى أدنى ميل.</p>\n<p>استخدم زر قارن بعد كل تغيير: يُظهر الأصل بجانب النسخة المدورة، فيسهل ملاحظة عندما تجاوزت الحد.</p>\n<h2 id=\"using-custom-angles\">زوايا مخصصة للصور المائلة</h2>\n<p>الزوايا المخصصة للصور غير المستقيمة تمامًا: صورة شاطئ بأفق مائل أو صفحة ممسوحة ضوئيًا ملتوية قليلًا تدخل في هذه المجموعة.</p>\n<p>اسحب منزلق زاوية التدوير ببطء وراقب الأفق: تتحدث المعاينة حيًا، فتستطيع التوقف فور أن يبدو الخط مستويًا. وانقر تطبيق الزاوية لتأكيد القيمة، أو إعادة ضبط إلى 0° للبدء من جديد: تستطيع الضبط بقدر ما تريد قبل التنزيل، إذ لا يُحفظ شيء حتى التصدير.</p>\n<p>تذكر أن زاوية مخصصة توسّع اللوحة: تكتسب زوايا الإطار مناطق مثلثة صغيرة، تظهر كلون صلب في JPG أو كشفافية في PNG.</p>\n<h2 id=\"flipping-a-mirrored-selfie\">كيف تقلب صورة شخصية معكوسة</h2>\n<p>صورة شخصية معكوسة سهلة الاكتشاف: نص قميص يُقرأ معكوسًا. والحل نقرة على قلب أفقي، تعكس الصورة عودة إلى الطبيعي.</p>\n<p>اقلب قبل أن تدوّر إذا احتاجت الصورة الحركتين: الترتيب أقل أهمية من مراجعة المعاينة، لكن القلب أولًا يبقي المنطق بسيطًا. وراجع أكثر من النص: قلب ينقل كل شيء إلى الجانب المقابل، بما فيه فرق الشعر أو شامة أو لافتة في الخلفية، فانظر إلى الصورة كاملة.</p>\n<p>وإذا بدت الصورة الشخصية جيدة بعد القلب، نزّلها. وإذا ما زالت تبدو غريبة، فقد تكون المشكلة التدوير لا المرآة، فجرّب دوران 90 درجة.</p>\n<h2 id=\"rotating-a-batch\">كيف تدوّر دفعة كاملة من الصور</h2>\n<p>ارفع دفعة واحدة كل الصور التي تشترك في نفس المشكلة: تطبق الأداة التدوير المختار على كل صورة في القائمة في نفس الوقت.</p>\n<p>يعمل هذا أفضل عندما تكون مشكلة الاتجاه متساوية في كلها: مجلد صور التُقطت كلها عموديًا، مثلًا، يحتاج نفس دوران 90 درجة. وإذا احتاجت الصور زوايا مختلفة، افصلها إلى مجموعات: دوّر مجموعة ونزّلها، ثم امسح القائمة ودوّر المجموعة التالية.</p>\n<p>استخدم تنزيل الكل (ZIP) للدفعات: كل ملف يحتفظ باسمه الأصلي داخل ZIP، فلا يختلط شيء عند فك الضغط.</p>\n<h2 id=\"choosing-output-format\">كيف تختار صيغة الإخراج</h2>\n<p>الصيغة الأصلية هي الخيار الأكثر أمانًا عندما تحتاج فقط تصحيح الاتجاه: تبقي نوع الملف دون تغيير وتتجنب مفاجآت إعادة الترميز.</p>\n<p>JPG هو الخيار الأفضل للصور التي تنوي مشاركتها أو رفعها: يبقي الملفات صغيرة ويعمل في كل مكان، بما فيه النماذج القديمة وتطبيقات المراسلة. وPNG هو الخيار الصحيح للقطات الشاشة والشعارات والرسوم ذات النص: يحافظ على الحواف حادة والشفافية، وهو ما لا يستطيع JPG فعله.</p>\n<p>WebP يقع بين الاثنين: يقدم ملفات أصغر من JPG بجودة أفضل، لكن بعض الأنظمة القديمة ما زالت ترفضه، فراجع وجهتك أولًا.</p>\n<h2 id=\"checking-your-result\">كيف تراجع نتيجتك قبل التنزيل</h2>\n<p>راجع المعاينة دائمًا قبل التنزيل: زر قارن يُظهر الأصل والنسخة المدورة معًا، وهو أسرع طريقة لتأكيد التصحيح.</p>\n<p>انظر إلى حواف الصورة بعد تدوير بزاوية مخصصة: قد تكون اللوحة الموسعة أضافت مناطق في الزوايا لم تتوقعها، وقد تريد قصها. وراجع أيضًا حجم الملف: JPG مدور يجب أن يزن تقريبًا مثل الأصل، وقفزة كبيرة غالبًا تعني أن الجودة أو الصيغة تغيرت.</p>\n<p>وإذا بدا شيء خطأ، استخدم ضوابط التراجع أو إعادة الضبط: تصحيح الزاوية الآن أسرع من إعادة تعديل الملف المنزّل.</p>\n<h2 id=\"fixing-scanned-documents\">كيف تصحح مستندات ممسوحة ضوئيًا</h2>\n<p>الصفحات الممسوحة ضوئيًا هي أكثر أعمال التدوير شيوعًا بعد الصور: صفحة تدخل الماسح مقلوبة تخرج مقلوبة، والحل دوران 180 درجة.</p>\n<p>لصفحة ممسوحة مائلة، استخدم 90 درجة: اقرأ سطر نص بعد التدوير لتأكيد أنه يجري من اليسار إلى اليمين، وهو الاتجاه الصحيح لمعظم المستندات. والميلانات الصغيرة في المسحات شائعة أيضًا: صفحة ملتوية قليلًا في الماسح تحتاج زاوية مخصصة درجة أو درجتين لتستقيم.</p>\n<p>قوّم مسحًا قبل قصه: إذا قصصت أولًا، سيغيّر التدوير شكل الإطار وقد يقطع هامشًا أردت الاحتفاظ به.</p>\n<h2 id=\"rotating-on-mobile\">كيف تدوّر صورًا على الهاتف أو الجهاز اللوحي</h2>\n<p>تعمل الأداة على شاشات اللمس، فتستطيع تصحيح صورة مائلة على الهاتف نفسه الذي التقطها: ارفعها من معرضك والمس زر التدوير ونزّل النتيجة.</p>\n<p>اسحب منزلق الزاوية بإصبعك للزوايا المخصصة: المعاينة كبيرة بما يكفي للحكم على أفق مائل، حتى على شاشة صغيرة. وتدوير الدفعة يعمل أيضًا على الهاتف، مع أن رفع ملفات كبيرة كثيرة باتصال بطيء يستغرق وقتًا أطول: قم بالدفعات الكبيرة على حاسوب عندما تستطيع.</p>\n<p>تصل الملفات المنزّلة إلى مجلد التنزيلات المعتاد لديك. ومن هناك يمكنك مشاركتها مباشرة إلى تطبيق محادثة أو بريد أو منشور اجتماعي.</p>\n<h2 id=\"troubleshooting\">حل المشاكل: عندما لا يثبت التدوير</h2>\n<p>أحيانًا تبدو صورة مصححة في الأداة لكنها تعود مائلة بعد التنزيل: هذا غالبًا يعني أن الملف الأصلي كان له ملاحظة اتجاه EXIF ما زال عارض يقرؤها.</p>\n<p>الحل هو تدوير الملف المنزّل مرة أخرى في الأداة، أو فتحه في عارض آخر لتأكيد أن البكسلات مستقيمة حقًا: تعيد الأداة كتابة البكسلات، فالاتجاه يُخبز في الصورة نفسها. ومشكلة شائعة أخرى صورة تدور في الاتجاه الخطأ: تراجع عن الدوران ودوّر إلى الجانب الآخر، إذ يعطي 90 درجة باتجاه عقارب الساعة و90 درجة عكس عقارب الساعة نتيجتين متعاكستين.</p>\n<p>وإذا استمرت زاوية مخصصة في قص الزوايا، تذكر أن اللوحة تتوسع تلقائيًا: الزوايا لا تُقص؛ تُملأ، وتستطيع قص ذلك الملء بعدها.</p>\n<h2 id=\"quick-tips\">نصائح سريعة لتدوير أسرع</h2>\n<p>الصق لقطات الشاشة مباشرة بـCtrl+V بدل حفظها أولًا: تقبل الأداة صور الحافظة، ما يوفر خطوة عندما تصحح لقطة.</p>\n<p>تعود على التسلسل: ارفع ودوّر وقارن ونزّل. تلك الحركات الأربع تحل تقريبًا أي مشكلة اتجاه تواجهها. واحتفظ بالملف الأصلي حتى تراجع التنزيل: إذا كانت النتيجة خطأ، تستطيع البدء من جديد من الأصل النظيف بدل إعادة تعديل نسخة تالفة.</p>\n<p>سمِّ تنزيلاتك أسماء واضحة عندما تدوّر دفعة: مجلد ملفات مدورة بأسماء واضحة أسهل ترتيبًا بكثير من مجموعة تنزيلات متطابقة.</p>\n<h2 id=\"rotating-animated-gifs\">كيف تدوّر GIF متحركة</h2>\n<p>يمكن تدوير GIF المتحركة، لكن النتيجة تعتمد على الأداة والملف: تقبل أداة التدوير والقلب ملفات GIF، ويُطبق التدوير على إطارات الحركة.</p>\n<p>راجع النتيجة بعناية بعد تدوير GIF: بعض الحركات لها إطارات كثيرة، وتدوير يبدو جيدًا في الإطار الأول يجب مراجعته في الإطارات التالية أيضًا. وانتبه إلى حجم الملف: GIF كبير أصلًا قد ينمو قليلًا بعد إعادة رسمه، فقارن حجم التنزيل مع الأصل قبل مشاركته.</p>\n<p>وإذا انكسرت الحركة أو بدت سيئة بعد التدوير، فالحل الأكثر أمانًا هو تدوير الإطارات الثابتة قبل تجميعها في GIF: منشئ GIF يبدأ من صور موجهة جيدًا يتجنب المشكلة تمامًا.</p>\n<h2 id=\"rotation-for-id-photos\">كيف تدوّر صور هوية وجواز سفر</h2>\n<p>يجب أن تكون صور الهوية مستقيمة وأمامية ومؤطرة جيدًا، وصورة هوية مائلة تُرفض دون نقاش: التدوير هو الحل، لكن يجب أن يتم بعناية.</p>\n<p>راجع قواعد البوابة قبل التدوير: بعض البوابات تتطلب أبعادًا دقيقة بالبكسلات إضافة إلى الاتجاه الصحيح، فدوران 90 درجة قد يغيّر الأبعاد التي تحتاجها. ودوّر الصورة الأصلية، لا نسخة ضُغطت مسبقًا: صورة هوية تحتاج وجهًا حادًا، وكل حفظ إضافي ينعّم التفاصيل التي تراجعها البوابة.</p>\n<p>بعد التدوير، قص الصورة إلى النسبة المطلوبة وراجع موضع الوجه: يجب أن يبقى الوجه في الوسط، مع قليل من المساحة فوقه، وأن تبقى الخلفية ناعمة وفاتحة.</p>\n<h2 id=\"rotation-shortcuts\">اختصارات لوحة المفاتيح والحافظة</h2>\n<p>اللصق بـCtrl+V هو أسرع طريقة لإدخال لقطة شاشة إلى الأداة: انسخ الصورة من أي برنامج والصقها مباشرة في منطقة الرفع وتخطَّ خطوة الحفظ.</p>\n<p>وللملفات الموجودة على جهازك، سحبها إلى منطقة الرفع أسرع من التصفح عبر المجلدات: أسقط ملفًا أو دفعة كاملة دفعة واحدة. واستخدم زر قارن بعد كل تدوير، لا في النهاية فقط: مراجعة سريعة بعد كل تغيير تكتشف دورانًا في الاتجاه الخطأ قبل أن يصبح خطأ منزّلًا.</p>\n<p>تعلّم ضوابط التراجع: دوران خطأ يُصحح بنقرة واحدة، بينما خطأ منزّل يكلف وقت رفع الصورة وتدويرها مجددًا.</p>\n<h2 id=\"rotation-vs-other-tools\">التدوير مقابل أدوات التعديل الأخرى</h2>\n<p>التدوير يغيّر الاتجاه، لكنه لا يغيّر الحجم أو اللون أو الحدة: إذا كانت صورة كبيرة جدًا أو داكنة جدًا أو باهتة جدًا، فتدويرها وحدها لن يصلحها.</p>\n<p>اجمع التدوير مع <a href=\"/ar/taghyir-hajm-as-suwar/\">مغيّر حجم الصور</a> عندما تحتاج الصورة أبعادًا جديدة لنموذج أو ملف شخصي: غيّر الحجم بعد التدوير، لتطابق الأبعاد الاتجاه الجديد. واجمعه مع <a href=\"/ar/taadil-sutoo-as-sura/\">محرر سطوع الصورة</a> عندما تكون صورة مائلة داكنة جدًا أيضًا: التفتيح بعد التدوير يبقي السير بسيطًا والنتيجة متوقعة.</p>\n<p>واجمعه مع <a href=\"/ar/qass-as-suwar/\">قاص الصور</a> عندما تكون للصورة المدورة زوايا فارغة أو حافة مشتتة: قص في النهاية، عندما يكون الاتجاه محددًا بالفعل، ليتطابق التأطير مع الصورة المدورة.</p>\n<p>لشرح أكمل لماذا تدور الصور وحدها، اقرأ <a href=\"/ar/blog/ittijah-as-sura-wa-tadweer-exif/\">اتجاه الصورة: مشاكل تدوير EXIF موضحة</a>. وللدليل الكامل، راجع <a href=\"/ar/blog/dalil-tadweer-wa-qalb-as-suwar/\">دليل تدوير وقلب الصور الكامل</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أدوّر صورة 90 درجة على هاتفي؟","answer":"افتح أداة تدوير وقلب الصورة في متصفح هاتفك وارفع الصورة من معرضك والمس تدوير 90° إلى اليسار أو تدوير 90° إلى اليمين. واستخدم زر قارن لمراجعة النتيجة ثم نزّل الملف."},{"question":"هل يمكنني تدوير صورة دون فقدان جودة الصورة؟","answer":"نعم، لدورانات 90 و180 درجة تُعاد ترتيب البكسلات دون فقدان جودة تقريبًا. والزوايا المخصصة تعيد رسم الصورة، فاختر PNG أو ضبط جودة JPG مرتفعًا ليبقى الناتج حادًا."},{"question":"كيف أصلح صورة مقلوبة؟","answer":"ارفع الصورة وانقر زر 180°: نصف دوران يصحح صورة مقلوبة تمامًا مهما كان الاتجاه. وراجع المعاينة لتأكيد أن الموضوع أصبح مستقيمًا ثم نزّل الملف."},{"question":"هل يمكنني تدوير صور عدة في نفس الوقت؟","answer":"نعم، ارفع كل الصور التي تحتاج نفس التدوير واختر الزاوية مرة واحدة وتطبقها الأداة على القائمة كلها. ونزّل الكل كملف ZIP. وإذا احتاجت الصور زوايا مختلفة، دوّرها في مجموعات."},{"question":"لماذا تبقى صورتي مائلة بعد تدويرها؟","answer":"قد يحمل الملف الأصلي ملاحظة اتجاه EXIF ما زال عارضك يقرؤها خطأ، أو ذهب التدوير في الاتجاه الخطأ. وجرّب تدوير 90 درجة في الاتجاه المعاكس وراجع الملف المنزّل في عارض آخر."},{"question":"كيف أقوّم صورة مائلة قليلًا فقط؟","answer":"استخدم منزلق زاوية التدوير المخصص واسحبه ببطء وأنت تراقب المعاينة: درجة أو درجتان غالبًا تكفيان لأفق مائل. وانقر تطبيق الزاوية عندما يبدو الخط مستويًا."}];
